As a senior cloud solutions architect, I'd like to emphasize the importance of defense-in-depth security practices when designing multi-tenant SaaS deployments.

When it comes to infrastructure, there are often trade-offs between cost, performance, and operational complexity. For instance, using serverless functions can provide scalability and cost savings, but it may require more complex event-driven patterns and managed databases to ensure data consistency and security.

Here's an example of how we can use Terraform to create a sample infrastructure for a multi-tenant SaaS application:
```
# File: main.tf

provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "example" {
  bucket = "my-saas-bucket"
}

resource "aws_s3_bucket_policy" "example" {
  bucket = aws_s3_bucket.example.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowRead"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:GetObject"
        Resource = aws_s3_bucket.example.arn
      }
    ]
  })
}

resource "aws_iam_user" "example" {
  name = "my-saas-user"
}

resource "aws_iam_policy" "example" {
  name        = "my-saas-policy"
  description = "Policy for my SaaS application"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowRead"
        Effect    = "Allow"
        Action    = "s3:GetObject"
        Resource = aws_s3_bucket.example.arn
      }
    ]
  })
}

resource "aws_iam_role" "example" {
  name        = "my-saas-role"
  description = "Role for my SaaS application"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "example" {
  role       = aws_iam_role.example.name
  policy_arn = aws_iam_policy.example.arn
}

resource "aws_s3_bucket_policy_attachment" "example" {
  bucket = aws_s3_bucket.example.id
  policy = aws_iam_policy.example.arn
}
```
This example creates a sample SaaS application with a S3 bucket, policy, and IAM user. It also creates a policy and role for the SaaS application, and attaches the policy to the S3 bucket.

When designing your own infrastructure, keep in mind the trade-offs between cost, performance, and operational complexity. Consider using serverless functions and managed databases to reduce costs, but ensure that your event-driven patterns and security measures are in place to protect your data.

Remember to always follow defense-in-depth security practices to protect your customers' data.

